function tidyPublicCardPositions(count) {
  const zone = TABLE_GEOMETRY.homeZone;
  const cardWidth = TABLE_GEOMETRY.cardWidth;
  const cardHeight = TABLE_GEOMETRY.cardHeight;
  const edge = 42;
  const clearance = 44;
  const gap = 22;
  const step = cardWidth + gap;
  const leftStart = zone.x + edge;
  const leftEnd = TABLE_GEOMETRY.deck.x - clearance - cardWidth;
  const rightStart = TABLE_GEOMETRY.deck.x + cardWidth + clearance;
  const rightEnd = zone.x + zone.width - edge - cardWidth;
  const rowXs = [];

  for (let x = leftStart; x <= leftEnd; x += step) rowXs.push(x);
  for (let x = rightStart; x <= rightEnd; x += step) rowXs.push(x);
  rowXs.sort((left, right) => left - right);

  const safeRows = [
    zone.y + 58,
    zone.y + zone.height - cardHeight - 44
  ];
  const positions = [];
  for (const y of safeRows) {
    for (const x of rowXs) positions.push({ x, y });
  }

  if (count > positions.length) {
    const fallbackColumns = Math.max(1, Math.floor((zone.width - edge * 2 + gap) / step));
    const fallbackRows = Math.ceil((count - positions.length) / fallbackColumns);
    const availableHeight = Math.max(0, zone.height - cardHeight - edge * 2);
    const rowStep = fallbackRows <= 1
      ? 0
      : Math.max(24, Math.min(cardHeight + gap, availableHeight / (fallbackRows + 1)));
    for (let row = 0; positions.length < count; row += 1) {
      const remaining = Math.min(fallbackColumns, count - positions.length);
      const rowWidth = cardWidth * remaining + gap * Math.max(0, remaining - 1);
      const startX = zone.x + (zone.width - rowWidth) / 2;
      const y = clamp(zone.y + edge + (row + 1) * rowStep, zone.y + edge, zone.y + zone.height - cardHeight - edge);
      for (let column = 0; column < remaining; column += 1) {
        positions.push({ x: startX + column * step, y });
      }
    }
  }

  return positions.slice(0, count);
}

