function checkResourceCapacity(room, extraCards = 0, extraObjects = 0, extraDecks = 0) {
  if (room.cards.size + extraCards > 1500 || room.objects.size + room.tokens.size + extraObjects > 240 || room.decks.size + extraDecks > 32) {
    throw new RoomError("TABLE_FULL", "桌面有点挤了，先收起一些物件再添加。", 409);
  }
}

function addRoomPack(room, playerId, pack, position = {}) {
  const actor = requirePlayer(room, playerId);
  validateGamePack(pack);
  checkResourceCapacity(room, pack.cards.length, (pack.tokens || []).length, 1);
  const point = publicDropPoint({ x: position.x ?? 1100, y: position.y ?? 400 });
  const fresh = createRoom({ code: room.code, pack });
  const deckId = `deck_${randomUUID().replaceAll("-", "")}`;
  const deck = fresh.decks.get("main");
  deck.id = deckId;
  deck.x = point.x;
  deck.y = point.y;
  saveUndoPoint(room);
  deck.z = room.nextZ++;
  room.decks.set(deckId, deck);
  for (const card of fresh.cards.values()) {
    card.deckId = deckId;
    room.cards.set(card.id, card);
  }
  for (const [index, token] of [...fresh.tokens.values()].entries()) {
    Object.assign(token, publicTokenDropPoint({ x: point.x + 135 + index * 76, y: point.y + 40 }), { packId: pack.id, z: room.nextZ++ });
    token.homeX = token.x;
    token.homeY = token.y;
    room.tokens.set(token.id, token);
  }
  addHistory(room, actor, `拿出了「${pack.name}」`, { action: "add-pack" });
  touch(room);
  return deckId;
}

function requireResource(room, type, id) {
  const map = type === "card" ? room.cards : type === "token" ? room.tokens : type === "deck" ? room.decks : type === "object" ? room.objects : null;
  const resource = map?.get(String(id));
  if (!resource) throw new RoomError("RESOURCE_NOT_FOUND", "这个物件已经不在桌上。", 404);
  if (resource.bagId || resource.hidden || (type === "card" && ["deck", "bag"].includes(resource.zone))) {
    throw new RoomError("RESOURCE_HIDDEN", "先从容器取出这个物件。", 403);
  }
  return { map, resource };
}

function requireControllableResource(room, actor, type, id) {
  const result = requireResource(room, type, id);
  if (type === "card" && !canControlCard(actor, result.resource)) throw new RoomError("NO_CONTROL", "这张牌不由你操作。", 403);
  return result;
}

function tableSelectionResources(room, references) {
  if (!Array.isArray(references) || !references.length || references.length > 1800) {
    throw new RoomError("INVALID_SELECTION", "请先选择要移动的桌面物件。");
  }
  const selected = new Map();
  for (const ref of references) {
    if (!ref || !["card", "deck", "token", "object"].includes(ref.type) || typeof ref.id !== "string") {
      throw new RoomError("INVALID_SELECTION", "多选中包含无法识别的物件。");
    }
    const { resource } = requireResource(room, ref.type, ref.id);
    if (ref.type === "card" && resource.zone !== "public") {
      throw new RoomError("PRIVATE_SELECTION", "批量整理只移动桌面物件，手牌请单独操作。", 403);
    }
    selected.set(`${ref.type}:${ref.id}`, { type: ref.type, value: resource });
  }
  return [...selected.values()].sort((a, b) => a.value.z - b.value.z);
}

function tableResourceBounds(type, resource) {
  const width = type === "token" ? TABLE_GEOMETRY.tokenSize : type === "object" ? resource.width || 94 : TABLE_GEOMETRY.cardWidth;
  const height = type === "token" ? TABLE_GEOMETRY.tokenSize : type === "object" ? resource.height || 138 : TABLE_GEOMETRY.cardHeight;
  const rotation = type === "card" || type === "object" ? resource.rotation || 0 : 0;
  const angle = rotation * Math.PI / 180;
  const rotatedWidth = Math.abs(width * Math.cos(angle)) + Math.abs(height * Math.sin(angle));
  const rotatedHeight = Math.abs(width * Math.sin(angle)) + Math.abs(height * Math.cos(angle));
  return { x: resource.x + (width - rotatedWidth) / 2, y: resource.y + (height - rotatedHeight) / 2, width: rotatedWidth, height: rotatedHeight };
}

function tableSelectionDelta(resources, x, y) {
  const dx = Number(x), dy = Number(y);
  if (!Number.isFinite(dx) || !Number.isFinite(dy) || !resources.length) throw new RoomError("INVALID_DROP", "没有收到有效的移动距离。");
  const bounds = resources.map(({ type, value }) => tableResourceBounds(type, value));
  const left = Math.min(...bounds.map((rect) => rect.x)), top = Math.min(...bounds.map((rect) => rect.y));
  const right = Math.max(...bounds.map((rect) => rect.x + rect.width)), bottom = Math.max(...bounds.map((rect) => rect.y + rect.height));
  const zone = TABLE_GEOMETRY.publicZone;
  if (right - left > zone.width - 36 || bottom - top > zone.height - 56) throw new RoomError("SELECTION_TOO_LARGE", "这些物件相距太远，请分组移动。", 409);
  return { dx: clamp(dx, zone.x + 18 - left, zone.x + zone.width - 18 - right), dy: clamp(dy, zone.y + 28 - top, zone.y + zone.height - 28 - bottom) };
}

function objectDropPoint(command, object) {
  const point = publicDropPoint(command);
  const zone = TABLE_GEOMETRY.publicZone;
  return {
    x: clamp(point.x, zone.x + 18, zone.x + zone.width - (object.width || 94) - 18),
    y: clamp(point.y, zone.y + 28, zone.y + zone.height - (object.height || 138) - 28)
  };
}

function applyResourceCommand(room, actor, command) {
  const commit = (label, createdResource) => { addHistory(room, actor, label); touch(room); return createdResource ? { createdResource } : true; };
  if (command.type === "move-resources") {
    const resources = tableSelectionResources(room, command.resources);
    resources.forEach(({ value }) => assertUnlocked(value));
    for (const ref of command.resources) {
      if (ref.x === undefined && ref.y === undefined) continue;
      const { resource } = requireResource(room, ref.type, ref.id);
      if (!Number.isFinite(ref.x) || !Number.isFinite(ref.y) || Math.abs(ref.x - resource.x) > .001 || Math.abs(ref.y - resource.y) > .001) {
        throw new RoomError("SELECTION_CHANGED", "选中的物件已被移动，请重新拖动。", 409);
      }
    }
    const { dx, dy } = tableSelectionDelta(resources, command.dx, command.dy);
    if (!dx && !dy) return true;
    saveUndoPoint(room);
    for (const { value } of resources) Object.assign(value, { x: value.x + dx, y: value.y + dy });
    return commit(`一起移动了 ${resources.length} 件物件`);
  }
  if (command.type === "stack-onto" && ["token", "token-stack"].includes(command.resourceType)) {
    if (command.targetType !== "token") throw new RoomError("INVALID_TARGET", "只能把筹码叠到另一枚筹码上。");
    const sourcePile = requireTokenStack(room, command.resourceId, command.resourceType === "token-stack");
    const source = command.resourceType === "token-stack" ? sourcePile : [requireToken(room, String(command.resourceId))];
    const target = requireTokenStack(room, command.targetId);
    const ids = new Set(source.map((token) => token.id));
    if (target.some((token) => ids.has(token.id))) throw new RoomError("SAME_PILE", "这些筹码已经在同一叠里。", 409);
    const tokens = [...target, ...source];
    tokens.forEach(assertUnlocked);
    const anchor = target.at(-1), zone = TABLE_GEOMETRY.publicZone;
    const depth = Math.min(tokens.length - 1, 6) * 2;
    const point = publicTokenDropPoint({ x: anchor.x, y: Math.min(anchor.y, zone.y + zone.height - TABLE_GEOMETRY.tokenSize - 28 - depth) });
    saveUndoPoint(room);
    tokens.forEach((token, index) => Object.assign(token, { x: point.x, y: point.y + Math.min(tokens.length - 1 - index, 6) * 2, z: room.nextZ++ }));
    return commit(`将 ${source.length} 枚筹码叠到了顶部，共 ${tokens.length} 枚`, { type: "token", id: source.at(-1).id });
  }
  if (["move-token-stack", "spread-token-stack", "take-token"].includes(command.type)) {
    const tokens = requireTokenStack(room, command.tokenId, true);
    tokens.forEach(assertUnlocked);
    if (command.type === "move-token-stack") {
      const anchor = tokens.find((token) => token.id === command.tokenId), point = publicTokenDropPoint(command), zone = TABLE_GEOMETRY.publicZone;
      const dx = clamp(point.x - anchor.x, zone.x + 18 - Math.min(...tokens.map((token) => token.x)), zone.x + zone.width - TABLE_GEOMETRY.tokenSize - 18 - Math.max(...tokens.map((token) => token.x)));
      const dy = clamp(point.y - anchor.y, zone.y + 28 - Math.min(...tokens.map((token) => token.y)), zone.y + zone.height - TABLE_GEOMETRY.tokenSize - 28 - Math.max(...tokens.map((token) => token.y)));
      saveUndoPoint(room);
      tokens.forEach((token) => Object.assign(token, { x: token.x + dx, y: token.y + dy, z: room.nextZ++ }));
      return commit(`移动了一叠 ${tokens.length} 枚筹码`);
    }
    if (command.type === "take-token") {
      const token = tokens.at(-1), point = openTokenSlot(room, token);
      saveUndoPoint(room);
      Object.assign(token, point, { z: room.nextZ++ });
      return commit("从筹码堆取出了一枚", { type: "token", id: token.id });
    }
    const positions = spreadStackPositions([...tokens].reverse(), command.layout || "grid", tokens.at(-1), { width: TABLE_GEOMETRY.tokenSize, height: TABLE_GEOMETRY.tokenSize });
    saveUndoPoint(room);
    positions.forEach(({ card: token, x, y }) => Object.assign(token, { x, y, z: room.nextZ++ }));
    return commit(`展开了一叠 ${tokens.length} 枚筹码`);
  }
  if (command.type === "stack-onto") {
    if (!["card", "stack", "deck"].includes(command.resourceType) || !["card", "deck"].includes(command.targetType)) {
      throw new RoomError("INVALID_TARGET", "只能把卡牌叠到公共牌或牌堆上。");
    }
    const publicPile = (id) => {
      const card = requireCard(room, String(id));
      if (card.zone !== "public") throw new RoomError("CARD_NOT_PUBLIC", "只能叠到公共区的牌上。");
      try { return publicStackForCard(room, card.id); }
      catch (error) { if (error.code === "STACK_TOO_SMALL") return [card]; throw error; }
    };
    const sourceDeck = command.resourceType === "deck" ? requireDeck(room, command.resourceId) : null;
    const sourceCards = sourceDeck ? sourceDeck.order.map((id) => requireCard(room, id))
      : command.resourceType === "stack" ? publicStackForCard(room, String(command.resourceId))
      : [requireControllableResource(room, actor, "card", command.resourceId).resource];
    if (!sourceCards.length) throw new RoomError("DECK_EMPTY", "这叠牌已经空了。", 409);
    if (sourceDeck) assertUnlocked(sourceDeck);
    sourceCards.forEach(assertUnlocked);
    const targetCards = command.targetType === "card" ? publicPile(command.targetId) : [];
    targetCards.forEach(assertUnlocked);
    const sourceIds = new Set(sourceCards.map((card) => card.id));
    let deck = command.targetType === "deck" ? requireDeck(room, command.targetId) : null;
    if ((sourceDeck && deck === sourceDeck) || targetCards.some((card) => sourceIds.has(card.id))) {
      throw new RoomError("SAME_PILE", "这些牌已经在同一叠里。", 409);
    }
    if (!deck) {
      const anchor = targetCards.at(-1), origin = cardSource(room, anchor);
      const home = room.decks.get(anchor.deckId);
      if (!sourceDeck && !home?.hidden) checkResourceCapacity(room, 0, 0, 1);
      deck = sourceDeck || (home?.hidden ? home : {
        id: `deck_${randomUUID().replaceAll("-", "")}`, label: home?.label || "牌堆",
        packId: origin.packId, back: structuredClone(origin.back), locked: false, rotation: 0, order: []
      });
    }
    // All validation precedes the undo point: one drop is one atomic change.
    saveUndoPoint(room);
    if (targetCards.length) {
      const anchor = targetCards.at(-1);
      Object.assign(deck, { x: anchor.x, y: anchor.y, z: room.nextZ++, order: [] });
      room.decks.set(deck.id, deck);
      putCardsOnDeck(room, deck, targetCards);
    }
    putCardsOnDeck(room, deck, sourceCards);
    if (sourceDeck && sourceDeck !== deck) {
      sourceDeck.order = [];
      // Cards outside the merged pile also need a valid place to return to.
      for (const card of room.cards.values()) if (card.deckId === sourceDeck.id) {
        const source = cardSource(room, card);
        card.source = { packId: source.packId, back: structuredClone(source.back) };
        card.deckId = deck.id;
      }
      if (sourceDeck.id === "main") sourceDeck.hidden = true;
      else room.decks.delete(sourceDeck.id);
    }
    return commit(`将 ${sourceCards.length} 张牌叠到了「${deck.label}」顶部`, { type: "deck", id: deck.id });
  }
  if (command.type === "spread-deck") {
    const deck = requireDeck(room, command.deckId);
    assertUnlocked(deck);
    const cards = [...deck.order].reverse().map((id) => requireCard(room, id));
    if (!cards.length) throw new RoomError("DECK_EMPTY", "这叠牌已经空了。", 409);
    const layout = command.layout || "row";
    const positions = spreadStackPositions(cards, layout, { x: deck.x + TABLE_GEOMETRY.cardWidth + 24, y: deck.y });
    saveUndoPoint(room);
    deck.order = [];
    for (const { card, x, y } of positions) Object.assign(card, { zone: "public", ownerId: null, x, y, z: room.nextZ++ });
    return commit(`将「${deck.label}」的 ${cards.length} 张牌${layout === "column" ? "纵向" : layout === "row" ? "横向" : "网格"}展开`);
  }
  if (command.type === "save-template") {
    if (room.templates.size >= 40) throw new RoomError("LIBRARY_FULL", "本桌最多保存 40 件资源，先移除一些再保存。", 409);
    const { resource } = requireControllableResource(room, actor, command.resourceType, command.resourceId);
    if (command.resourceType === "card") throw new RoomError("SAVE_DECK", "先将卡牌收回牌盒，再保存整副牌。");
    if (resource.kind === "bag" && resource.contents.length) throw new RoomError("BAG_NOT_EMPTY", "先清空袋子，再存入资源库。");
    if (command.resourceType === "deck" && !resource.order.length) throw new RoomError("DECK_EMPTY", "空牌盒不能保存为资源。", 409);
    const template = {
      id: `saved_${randomUUID().replaceAll("-", "")}`, label: cleanName(command.label, resource.label),
      kind: command.resourceType === "deck" ? "deck" : resource.kind || "token",
      type: command.resourceType, resource: structuredClone(resource), creatorId: actor.id,
      cards: command.resourceType === "deck" ? resource.order.map((id) => structuredClone(room.cards.get(id))) : [],
      count: command.resourceType === "deck" ? resource.order.length : 1
    };
    saveUndoPoint(room);
    room.templates.set(template.id, template);
    return commit(`将「${template.label}」存入资源库`);
  }
  if (command.type === "spawn-template") {
    const template = room.templates.get(String(command.templateId));
    if (!template) throw new RoomError("TEMPLATE_NOT_FOUND", "这件收藏已经被移除。", 404);
    checkResourceCapacity(room, template.cards.length, template.type === "deck" ? 0 : 1, template.type === "deck" ? 1 : 0);
    const copy = structuredClone(template.resource);
    copy.id = `${template.type}_${randomUUID().replaceAll("-", "")}`;
    Object.assign(copy, objectDropPoint(command, copy), { locked: false, label: template.label });
    saveUndoPoint(room);
    copy.z = room.nextZ++;
    if (template.type === "deck") {
      copy.order = shuffled(template.cards.map((source) => {
        const card = { ...structuredClone(source), id: `card_${randomUUID().replaceAll("-", "")}`, deckId: copy.id };
        room.cards.set(card.id, card);
        return card.id;
      }));
      room.decks.set(copy.id, copy);
    } else if (template.type === "token") {
      copy.homeX = copy.x; copy.homeY = copy.y;
      room.tokens.set(copy.id, copy);
    } else room.objects.set(copy.id, copy);
    return commit(`取出了收藏「${template.label}」`, { type: template.type, id: copy.id });
  }
  if (command.type === "delete-template") {
    const template = room.templates.get(String(command.templateId));
    if (!template) throw new RoomError("TEMPLATE_NOT_FOUND", "没有找到这件收藏。", 404);
    if (actor.role !== "host" && template.creatorId !== actor.id) throw new RoomError("NO_CONTROL", "只能移除自己保存的收藏。", 403);
    saveUndoPoint(room);
    room.templates.delete(template.id);
    return commit(`移除了收藏「${template.label}」`);
  }
  if (command.type === "spawn-resource") {
    const preset = RESOURCE_CATALOG.find((entry) => entry.id === command.resourceId);
    if (!preset) throw new RoomError("RESOURCE_NOT_FOUND", "资源库里没有这个物件。", 404);
    checkResourceCapacity(room, 0, 1);
    const point = objectDropPoint(command, preset);
    const id = `${preset.kind}_${randomUUID().replaceAll("-", "")}`;
    const object = { ...preset, id, resourceId: preset.id, ...point, rotation: 0, locked: false };
    delete object.description;
    if (preset.kind === "note") object.text = preset.text || "";
    if (["die", "counter"].includes(preset.kind)) { object.value = preset.kind === "die" ? null : 0; object.rollId = 0; }
    if (preset.kind === "bag") object.contents = [];
    saveUndoPoint(room);
    object.z = room.nextZ++;
    if (preset.kind === "token") {
      Object.assign(object, { key: preset.id, homeX: point.x, homeY: point.y });
      room.tokens.set(id, object);
    } else room.objects.set(id, object);
    return commit(`拿出了「${preset.label}」`, { type: preset.kind === "token" ? "token" : "object", id });
  }

  if (["move-resource", "lock-resource", "delete-resource", "duplicate-resource", "edit-resource", "roll-resource", "adjust-resource"].includes(command.type)) {
    const { map, resource } = requireControllableResource(room, actor, command.resourceType, command.resourceId);
    const type = command.resourceType;
    if (command.type === "move-resource") {
      assertUnlocked(resource);
      const point = objectDropPoint(command, resource);
      saveUndoPoint(room);
      Object.assign(resource, point, { z: room.nextZ++ });
      return commit(`移动了「${resource.label || "物件"}」`);
    }
    if (command.type === "lock-resource") {
      saveUndoPoint(room);
      resource.locked = !resource.locked;
      return commit(`${resource.locked ? "锁定" : "解锁"}了「${resource.label || "卡牌"}」`);
    }
    if (command.type === "edit-resource") {
      if (type !== "object" || !["note", "counter", "mat", "bag"].includes(resource.kind)) throw new RoomError("NOT_EDITABLE", "这个物件不能编辑。");
      const label = cleanName(command.label, resource.label);
      const text = String(command.text ?? resource.text ?? "").replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/g, "");
      if (text.length > 600) throw new RoomError("TEXT_TOO_LONG", "便签最多写 600 个字。");
      saveUndoPoint(room);
      resource.label = label;
      if (resource.kind === "note") resource.text = text;
      return commit(`更新了「${label}」`);
    }
    if (command.type === "roll-resource") {
      if (resource.kind !== "die") throw new RoomError("NOT_A_DIE", "这不是骰子。");
      saveUndoPoint(room);
      resource.value = randomInt(1, resource.sides + 1);
      resource.rollId++;
      return commit(`${resource.label}掷出了 ${resource.value}`);
    }
    if (command.type === "adjust-resource") {
      const delta = Number(command.delta);
      if (resource.kind !== "counter" || ![-1, 1].includes(delta)) throw new RoomError("INVALID_COUNTER_STEP", "计数器每次加一或减一。");
      if (Math.abs(resource.value + delta) > 9999) throw new RoomError("COUNTER_LIMIT", "计数器已经到达边界。", 409);
      saveUndoPoint(room);
      resource.value += delta;
      return commit(`把「${resource.label}」调到 ${resource.value}`);
    }
    assertUnlocked(resource);
    if (command.type === "delete-resource") {
      if (type === "deck") {
        if (resource.id === "main") throw new RoomError("MAIN_DECK", "起始牌堆留在桌上，可以收起其他牌盒。", 409);
        const inUse = [...room.cards.values()].some((card) => card.deckId === resource.id && card.zone !== "deck");
        if (inUse) throw new RoomError("DECK_IN_USE", "还有牌在外面，先收回这副牌再移除。", 409);
      }
      if (resource.kind === "bag" && resource.contents.length) throw new RoomError("BAG_NOT_EMPTY", "先取出袋子里的物件。", 409);
      saveUndoPoint(room);
      if (type === "deck") for (const id of resource.order) room.cards.delete(id);
      map.delete(resource.id);
      return commit(`收起了「${resource.label || "卡牌"}」`);
    }
    if (command.type === "duplicate-resource") {
      checkResourceCapacity(room, type === "card" ? 1 : type === "deck" ? resource.order.length : 0, ["object", "token"].includes(type) ? 1 : 0, type === "deck" ? 1 : 0);
      if (resource.kind === "bag" && resource.contents.length) throw new RoomError("BAG_NOT_EMPTY", "先把袋子清空，再复制。", 409);
      const copy = structuredClone(resource);
      copy.id = `${type}_${randomUUID().replaceAll("-", "")}`;
      Object.assign(copy, objectDropPoint({ x: (resource.x ?? 700) + 120, y: (resource.y ?? 400) + 30 }, copy), { locked: false });
      saveUndoPoint(room);
      copy.z = room.nextZ++;
      if (type === "deck") {
        copy.order = shuffled(resource.order.map((id) => {
          const card = { ...structuredClone(room.cards.get(id)), id: `card_${randomUUID().replaceAll("-", "")}`, deckId: copy.id };
          room.cards.set(card.id, card);
          return card.id;
        }));
      }
      if (type === "card" && copy.zone === "hand") { copy.handOrder = room.nextHandOrder++; placeInHand(room, copy, copy.ownerId); }
      if (type === "token") { copy.homeX = copy.x; copy.homeY = copy.y; }
      map.set(copy.id, copy);
      return commit(`复制了「${resource.label || "卡牌"}」`, { type, id: copy.id });
    }
  }

  if (command.type === "collect-deck") {
    const deck = requireDeck(room, command.deckId);
    const cards = [...room.cards.values()].filter((card) => card.deckId === deck.id && card.zone === "public").sort((left, right) => left.z - right.z);
    if (!cards.length) throw new RoomError("NO_PUBLIC_CARDS", "这副牌没有散落在桌上的牌。", 409);
    cards.forEach(assertUnlocked);
    saveUndoPoint(room);
    putCardsOnDeck(room, deck, cards);
    return commit(`将「${deck.label}」的 ${cards.length} 张散牌叠回顶部`);
  }

  if (command.type === "bag-put") {
    const bag = room.objects.get(String(command.bagId));
    if (bag?.kind !== "bag") throw new RoomError("BAG_NOT_FOUND", "没有找到这个袋子。", 404);
    let resources;
    if (command.resourceType === "stack") resources = publicStackForCard(room, String(command.resourceId)).map((resource) => ({ type: "card", resource }));
    else if (command.resourceType === "token-stack") resources = requireTokenStack(room, command.resourceId, true).map((resource) => ({ type: "token", resource }));
    else {
      const { resource } = requireControllableResource(room, actor, command.resourceType, command.resourceId);
      if (command.resourceType === "deck" || ["bag", "mat"].includes(resource.kind)) throw new RoomError("BAG_TOO_SMALL", "牌盒、棋盘和其他袋子不能装进袋子里。");
      resources = [{ type: command.resourceType, resource }];
    }
    resources.forEach(({ resource }) => assertUnlocked(resource));
    saveUndoPoint(room);
    for (const { type, resource } of resources) {
      if (type === "card") {
        rekeyCards(room, [resource]);
        Object.assign(resource, { zone: "bag", ownerId: null, faceUp: false, x: null, y: null, z: 0, handOrder: 0 });
      }
      resource.bagId = bag.id;
      bag.contents.push({ type, id: resource.id });
    }
    return commit(`往「${bag.label}」装入 ${resources.length} 个物件`);
  }

  if (command.type === "bag-draw") {
    const bag = room.objects.get(String(command.bagId));
    if (bag?.kind !== "bag") throw new RoomError("BAG_NOT_FOUND", "没有找到这个袋子。", 404);
    if (!bag.contents.length) throw new RoomError("BAG_EMPTY", "袋子还是空的，把牌或小物件拖进来。", 409);
    const index = randomInt(bag.contents.length);
    const entry = bag.contents[index];
    const map = entry.type === "card" ? room.cards : entry.type === "token" ? room.tokens : room.objects;
    const resource = map.get(entry.id);
    if (!resource) throw new RoomError("RESOURCE_NOT_FOUND", "袋子中的物件已经不在。", 409);
    saveUndoPoint(room);
    bag.contents.splice(index, 1);
    delete resource.bagId;
    if (entry.type === "card") {
      placeInHand(room, resource, actor.id);
    } else Object.assign(resource, objectDropPoint({ x: bag.x + 150, y: bag.y + 10 }, resource), { z: room.nextZ++ });
    return commit(`从「${bag.label}」摸出了一个物件`);
  }
  return false;
}

function applyCommand(room, playerId, command) {
  const previousId = room.history.at(-1)?.id;
  const previousUndo = room.undoStack.at(-1);
  const source = command?.type === "shuffle" ? room.decks.get(String(command.deckId || "main"))
    : command?.type === "shuffle-stack" ? room.cards.get(String(command.cardId || "")) : null;
  const effect = source ? { type: "shuffle", x: source.x, y: source.y } : null;
  const result = applyTabletopCommand(room, playerId, command);
  const entry = room.history.at(-1);
  if (entry && entry.id !== previousId) {
    entry.action = command.type;
    if (effect && Number.isFinite(effect.x) && Number.isFinite(effect.y)) entry.effect = effect;
    const snapshot = room.undoStack.at(-1);
    if (snapshot && snapshot !== previousUndo && command.type !== "undo") snapshot.actionId = entry.id;
  }
  return result;
}

function applyTabletopCommand(room, playerId, command) {
  const actor = requirePlayer(room, playerId);
  if (!command || typeof command.type !== "string") {
    throw new RoomError("INVALID_COMMAND", "无法识别这次操作。");
  }


  const resourceResult = applyResourceCommand(room, actor, command);
  if (resourceResult) return resourceResult === true ? undefined : resourceResult;

  if (command.type === "chat") {
    const text = String(command.text ?? "").replace(/[\u0000-\u001f\u007f]/g, " ").trim();
    if (!text || Array.from(text).length > 280) throw new RoomError("INVALID_CHAT", "消息需要 1–280 个字。");
    if (Date.now() - (actor.lastChatAt || 0) < 500) throw new RoomError("CHAT_TOO_FAST", "慢一点，上一句话刚送到。", 429);
    actor.lastChatAt = Date.now();
    room.messages.push({ id: randomUUID(), text, playerId: actor.id, name: actor.name, color: actor.color, at: Date.now() });
    room.messages = room.messages.slice(-60);
    touch(room);
    return;
  }
  if (command.type === "rename-player") {
    const requested = cleanName(command.name, "");
    if (!requested) throw new RoomError("INVALID_NAME", "昵称不能为空。");
    const previousName = actor.name;
    const nextName = uniqueName(room, requested, "玩家", actor.id);
    if (nextName === previousName) return;
    actor.name = nextName;
    addHistory(room, actor, `由「${previousName}」改名为「${nextName}」`);
    touch(room);
    return;
  }

  if (command.type === "accept-card-request") {
    const request = [...room.cardRequests.values()].find((item) => item.id === command.requestId);
    if (!request || request.expiresAt <= Date.now()) throw new RoomError("REQUEST_EXPIRED", "这个选牌标记已经消失，请让朋友重新选择。", 409);
    if (request.ownerId !== actor.id) throw new RoomError("NO_CONTROL", "只有牌的持有者可以交付这些牌。", 403);
    const recipient = requirePlayer(room, request.playerId);
    const cards = request.cardIds.map((id) => requireCard(room, id));
    if (cards.some((card) => card.zone !== "hand" || card.ownerId !== actor.id)) throw new RoomError("REQUEST_CHANGED", "其中的牌已经移动，请重新选择。", 409);
    cards.forEach(assertUnlocked);
    saveUndoPoint(room);
    for (const card of cards) placeInHand(room, card, recipient.id);
    room.cardRequests.delete(request.playerId);
    addHistory(room, actor, `把 ${cards.length} 张私有牌交给了 ${recipient.name}`);
    touch(room);
    return;
  }

  if (command.type === "arrange-hand") {
    const owner = requirePlayer(room, String(command.ownerId || actor.id));
    if (owner.id !== actor.id) throw new RoomError("NO_CONTROL", "只能整理自己的私人区。", 403);
    const cards = [...room.cards.values()].filter((card) => card.zone === "hand" && card.ownerId === owner.id).sort((a, b) => a.handOrder - b.handOrder);
    cards.forEach(assertUnlocked);
    if (!cards.length) return;
    saveUndoPoint(room);
    cards.forEach((card, index) => placeInHand(room, card, owner.id, privateSlot(privateZoneForPlayer(room, owner.id), index)));
    addHistory(room, actor, "整理了自己的私人区"); touch(room); return;
  }

  if (command.type === "undo") {
    if (actor.role !== "host") throw new RoomError("HOST_ONLY", "只有房主可以撤销牌桌操作。", 403);
    const snapshot = room.undoStack.pop();
    if (!snapshot) throw new RoomError("NOTHING_TO_UNDO", "还没有可以撤销的牌桌操作。", 409);
    restoreBoard(room, snapshot);
    addHistory(room, actor, "撤销了上一步操作", snapshot.actionId ? { undoOf: snapshot.actionId } : {});
    touch(room);
    return;
  }

  if (command.type === "leave-seat") {
    if (actor.role === "host") {
      throw new RoomError("HOST_CANNOT_LEAVE", "房主需要在终端关闭整个房间。", 409);
    }
    const returnedCards = removePlayers(room, [actor.id]);
    addHistory(room, actor, returnedCards > 0 ? `离开了牌桌，${returnedCards} 张私有牌已洗回牌叠` : "离开了牌桌");
    touch(room);
    return;
  }

  if (command.type === "cleanup-offline") {
    if (actor.role !== "host") throw new RoomError("HOST_ONLY", "只有房主可以清理离线席位。", 403);
    const offlineGuests = [...room.players.values()].filter(
      (player) => player.role === "guest" && player.connections === 0
    );
    if (offlineGuests.length === 0) {
      throw new RoomError("NO_OFFLINE_PLAYERS", "当前没有需要清理的离线席位。", 409);
    }
    const returnedCards = removePlayers(room, offlineGuests.map((player) => player.id));
    addHistory(
      room,
      actor,
      `清理了 ${offlineGuests.length} 个离线席位${returnedCards > 0 ? `，${returnedCards} 张私有牌已洗回牌叠` : ""}`
    );
    touch(room);
    return;
  }

  if (command.type === "draw") {
    const deck = requireDeck(room, command.deckId);
    const cardId = deck.order.at(-1);
    if (!cardId) throw new RoomError("DECK_EMPTY", "牌叠已经抽空了。", 409);
    const card = requireCard(room, cardId);
    const requestedOwnerId = String(command.ownerId ?? "");
    const targetOwnerId = requestedOwnerId || actor.id;
    const targetOwner = requirePlayer(room, targetOwnerId);
    const point = privateDropPoint(room, targetOwner.id, command);
    saveUndoPoint(room);
    deck.order.pop();
    placeInHand(room, card, targetOwner.id, point);
    addHistory(room, actor, targetOwner.id === actor.id ? "抽了一张牌" : `给 ${targetOwner.name} 发了一张牌`);
    touch(room);
    return;
  }

  if (command.type === "draw-public") {
    const deck = requireDeck(room, command.deckId);
    const cardId = deck.order.at(-1);
    if (!cardId) throw new RoomError("DECK_EMPTY", "牌叠已经抽空了。", 409);
    const point = publicDropPoint(command);
    const card = requireCard(room, cardId);
    saveUndoPoint(room);
    deck.order.pop();
    card.zone = "public";
    card.ownerId = actor.id;
    card.x = point.x;
    card.y = point.y;
    card.rotation = command.rotation === undefined ? card.rotation : clamp(Number(command.rotation) || 0, -180, 180);
    if (typeof command.faceUp === "boolean") card.faceUp = command.faceUp;
    card.z = room.nextZ;
    card.handOrder = 0;
    room.nextZ += 1;
    addHistory(room, actor, `从牌叠取了一张${card.faceUp ? "正面" : "背面"}朝上的牌`);
    touch(room);
    return;
  }

  if (command.type === "move-card") {
    const card = requireCard(room, String(command.cardId ?? ""));
    if (["deck", "bag"].includes(card.zone)) throw new RoomError("CARD_IN_DECK", "请从牌堆或袋子抽牌。");
    if (!canControlCard(actor, card)) throw new RoomError("NO_CONTROL", "这张牌不由你操作。", 403);
    assertUnlocked(card);

    if (command.target === "public") {
      const point = publicDropPoint(command);
      saveUndoPoint(room);
      card.zone = "public";
      card.x = point.x;
      card.y = point.y;
      card.rotation = clamp(Number(command.rotation) || 0, -180, 180);
      card.faceUp = command.faceUp !== false;
      card.z = room.nextZ;
      room.nextZ += 1;
      addHistory(room, actor, "把一张牌放到公共区");
      touch(room);
      return;
    }

    if (command.target === "hand") {
      const requestedOwnerId = String(command.ownerId ?? "");
      const targetOwnerId = requestedOwnerId || actor.id;
      const targetOwner = requirePlayer(room, targetOwnerId);
      const point = privateDropPoint(room, targetOwner.id, command, [card.id]);
      const reposition = card.zone === "hand" && card.ownerId === targetOwner.id;
      saveUndoPoint(room);
      placeInHand(room, card, targetOwner.id, point, command.rotation);
      addHistory(
        room,
        actor,
        reposition ? "调整了一张私有牌的位置" : targetOwner.id === actor.id ? "把一张牌收回私人区" : `把一张牌交给了 ${targetOwner.name}`
      );
      touch(room);
      return;
    }

    throw new RoomError("INVALID_TARGET", "只能把牌放进公共区或手牌区。");
  }

  if (command.type === "move-stack") {
    const cardId = String(command.cardId ?? "");
    const cards = publicStackForCard(room, cardId);
    const anchor = cards.find((card) => card.id === cardId);
    cards.forEach(assertUnlocked);

    if (command.target === "public") {
      const point = publicDropPoint(command);
      const zone = TABLE_GEOMETRY.publicZone;
      // Clamp one translation for the whole stack so edge drops cannot squash it.
      const dx = clamp(
        point.x - anchor.x,
        zone.x + 18 - Math.min(...cards.map((card) => card.x)),
        zone.x + zone.width - TABLE_GEOMETRY.cardWidth - 18 - Math.max(...cards.map((card) => card.x))
      );
      const dy = clamp(
        point.y - anchor.y,
        zone.y + 28 - Math.min(...cards.map((card) => card.y)),
        zone.y + zone.height - TABLE_GEOMETRY.cardHeight - 28 - Math.max(...cards.map((card) => card.y))
      );
      saveUndoPoint(room);
      for (const card of cards) {
        card.x += dx;
        card.y += dy;
        card.z = room.nextZ++;
      }
      addHistory(room, actor, `移动了一个 ${cards.length} 张的牌堆`);
      touch(room);
      return;
    }

    if (command.target === "hand") {
      const targetOwner = requirePlayer(room, String(command.ownerId || actor.id));
      saveUndoPoint(room);
      for (const card of cards) {
        placeInHand(room, card, targetOwner.id);
      }
      addHistory(room, actor, targetOwner.id === actor.id
        ? `把 ${cards.length} 张牌的牌堆收回手牌区`
        : `把 ${cards.length} 张牌的牌堆交给了 ${targetOwner.name}`);
      touch(room);
      return;
    }

    throw new RoomError("INVALID_TARGET", "只能把牌堆放进公共区或手牌区。");
  }

  if (command.type === "flip-card") {
    const card = requireCard(room, String(command.cardId ?? ""));
    if (!["public", "hand"].includes(card.zone)) throw new RoomError("CARD_NOT_PUBLIC", "请先把牌从牌堆或袋子里取出。");
    if (card.zone === "hand" ? card.ownerId !== actor.id : !canControlCard(actor, card)) throw new RoomError("NO_CONTROL", "只有持有者可以展示或收回自己的手牌。", 403);
    saveUndoPoint(room);
    card.faceUp = !card.faceUp;
    addHistory(room, actor, card.zone === "hand" ? card.faceUp ? "在私人区展示了一张手牌" : "收回了一张手牌的展示" : `把一张公共牌翻到${card.faceUp ? "正面" : "背面"}`);
    touch(room);
    return;
  }

  if (command.type === "shuffle-stack") {
    const cards = publicStackForCard(room, String(command.cardId ?? ""));
    cards.forEach(assertUnlocked);
    const anchor = cards.at(-1);
    saveUndoPoint(room);
    const shuffledCards = shuffled(cards, true);
    rekeyCards(room, shuffledCards);
    shuffledCards.forEach((card, index) => {
      card.zone = "public";
      card.ownerId = null;
      card.x = anchor.x + Math.min(index, 4) * 0.8;
      card.y = anchor.y + Math.min(index, 4) * 0.8;
      card.rotation = 0;
      card.z = room.nextZ;
      card.handOrder = 0;
      room.nextZ += 1;
    });
    addHistory(room, actor, `洗了一个 ${cards.length} 张的牌堆`);
    touch(room);
    return;
  }

  if (command.type === "draw-stack") {
    const cards = publicStackForCard(room, String(command.cardId ?? ""));
    cards.forEach(assertUnlocked);
    const topCard = cards.at(-1);
    saveUndoPoint(room);
    placeInHand(room, topCard, actor.id);
    addHistory(room, actor, `从 ${cards.length} 张的牌堆抽了一张牌`);
    touch(room);
    return;
  }

  if (command.type === "spread-stack") {
    const cards = publicStackForCard(room, String(command.cardId ?? ""));
    cards.forEach(assertUnlocked);
    const positions = spreadStackPositions([...cards].reverse(), command.layout || "row");
    saveUndoPoint(room);
    positions.forEach(({ card, x, y }, index) => {
      card.x = x;
      card.y = y;
      card.z = room.nextZ;
      room.nextZ += 1;
    });
    addHistory(room, actor, `展开了一个 ${cards.length} 张的牌堆`);
    touch(room);
    return;
  }

  if (command.type === "move-token") {
    const token = requireToken(room, String(command.tokenId ?? ""));
    assertUnlocked(token);
    if (token.bagId) throw new RoomError("IN_BAG", "先从袋子取出这个标记。", 409);
    const point = publicTokenDropPoint(command);
    saveUndoPoint(room);
    token.x = point.x;
    token.y = point.y;
    token.z = room.nextZ;
    room.nextZ += 1;
    addHistory(room, actor, `移动了「${token.label}」`);
    touch(room);
    return;
  }

  if (command.type === "roll-die") {
    saveUndoPoint(room);
    room.die.value = randomInt(1, room.die.sides + 1);
    room.die.rollId += 1;
    room.die.lastRolledBy = actor.id;
    addHistory(room, actor, `掷出了 ${room.die.value}`);
    touch(room);
    return;
  }

  if (command.type === "adjust-counter") {
    const delta = Number(command.delta);
    if (![1, -1].includes(delta)) {
      throw new RoomError("INVALID_COUNTER_STEP", "共享计数器每次只能加一或减一。");
    }
    const nextValue = clamp(room.counter.value + delta, room.counter.min, room.counter.max);
    if (nextValue === room.counter.value) {
      throw new RoomError("COUNTER_LIMIT", `${room.counter.label}已经到达可用范围。`, 409);
    }
    saveUndoPoint(room);
    room.counter.value = nextValue;
    addHistory(room, actor, `把「${room.counter.label}」调到 ${nextValue}`);
    touch(room);
    return;
  }

  if (command.type === "shuffle") {
    const deck = requireDeck(room, command.deckId);
    saveUndoPoint(room);
    const cards = deck.order.map((id) => requireCard(room, id));
    rekeyCards(room, cards);
    deck.order = shuffled(cards.map((card) => card.id), true);
    addHistory(room, actor, "洗了牌叠");
    touch(room);
    return;
  }

  if (command.type === "tidy-public") {
    if (actor.role !== "host") throw new RoomError("HOST_ONLY", "只有房主可以一键整理公共区。", 403);
    const publicCards = [...room.cards.values()]
      .filter((card) => card.zone === "public")
      .sort((left, right) => left.z - right.z);
    if (publicCards.length === 0) {
      throw new RoomError("NO_PUBLIC_CARDS", "公共区还没有可以整理的牌。", 409);
    }
    publicCards.forEach(assertUnlocked);
    const positions = tidyPublicCardPositions(publicCards.length);
    saveUndoPoint(room);
    publicCards.forEach((card, index) => {
      card.x = positions[index].x;
      card.y = positions[index].y;
      card.rotation = 0;
      card.z = room.nextZ;
      room.nextZ += 1;
    });
    addHistory(room, actor, `整理了公共区的 ${publicCards.length} 张牌`);
    touch(room);
    return;
  }

  if (command.type === "collect-public") {
    if (actor.role !== "host") throw new RoomError("HOST_ONLY", "只有房主可以收回公共牌。", 403);
    const publicCards = [...room.cards.values()].filter((card) => card.zone === "public").sort((left, right) => left.z - right.z);
    if (publicCards.length === 0) {
      throw new RoomError("NO_PUBLIC_CARDS", "公共区还没有可以收回的牌。", 409);
    }
    publicCards.forEach(assertUnlocked);
    saveUndoPoint(room);
    for (const deck of room.decks.values()) {
      const cards = publicCards.filter((card) => card.deckId === deck.id);
      if (cards.length) putCardsOnDeck(room, deck, cards);
    }
    addHistory(room, actor, `把 ${publicCards.length} 张公共牌叠回各自牌堆顶部`);
    touch(room);
    return;
  }

  if (["deal-one-each", "deal-each"].includes(command.type)) {
    if (actor.role !== "host") throw new RoomError("HOST_ONLY", "只有房主可以发牌。", 403);
    const deck = requireDeck(room, command.deckId);
    if (deck.order.length === 0) throw new RoomError("DECK_EMPTY", "牌叠已经抽空了。", 409);
    const count = command.type === "deal-one-each" ? 1 : Number(command.count);
    if (!Number.isInteger(count) || count < 1 || count > 10) {
      throw new RoomError("INVALID_DEAL_COUNT", "每次只能给每人发 1–10 张牌。");
    }
    const players = [...room.players.values()].sort((left, right) => left.seatIndex - right.seatIndex);
    const needed = players.length * count;
    if (deck.order.length < needed) {
      throw new RoomError(
        "NOT_ENOUGH_CARDS",
        `牌叠只剩 ${deck.order.length} 张，不够给 ${players.length} 位玩家每人发 ${count} 张。`,
        409
      );
    }
    saveUndoPoint(room);
    for (let round = 0; round < count; round += 1) {
      for (const player of players) {
        const cardId = deck.order.pop();
        const card = requireCard(room, cardId);
        placeInHand(room, card, player.id);
      }
    }
    addHistory(room, actor, `给每位玩家发了 ${count} 张牌`);
    touch(room);
    return;
  }

  if (["set-turn", "advance-turn", "random-turn"].includes(command.type)) {
    if (actor.role !== "host" && (command.type === "random-turn" || room.turn.activePlayerId !== actor.id)) {
      throw new RoomError("NOT_YOUR_TURN", "房主或当前回合者可以转交行动标记。", 403);
    }
    const seatedPlayers = [...room.players.values()].sort((left, right) => left.seatIndex - right.seatIndex);
    if (seatedPlayers.length === 0) throw new RoomError("NO_PLAYERS", "牌桌上还没有玩家。", 409);
    const onlinePlayers = seatedPlayers.filter((player) => player.connections > 0);
    const candidates = onlinePlayers.length > 0 ? onlinePlayers : seatedPlayers;
    let nextPlayer;

    if (command.type === "set-turn") {
      nextPlayer = requirePlayer(room, String(command.playerId ?? ""));
    } else if (command.type === "random-turn") {
      nextPlayer = candidates[randomInt(candidates.length)];
    } else {
      const currentIndex = candidates.findIndex((player) => player.id === room.turn.activePlayerId);
      nextPlayer = candidates[(currentIndex + 1 + candidates.length) % candidates.length];
    }

    saveUndoPoint(room);
    room.turn.activePlayerId = nextPlayer.id;
    addHistory(
      room,
      actor,
      command.type === "random-turn"
        ? `随机选中了 ${nextPlayer.name}`
        : `把行动标记交给了 ${nextPlayer.name}`
    );
    touch(room);
    return;
  }

  if (command.type === "reset") {
    if (actor.role !== "host") throw new RoomError("HOST_ONLY", "只有房主可以重置桌面。", 403);
    saveUndoPoint(room);
    const cards = [...room.cards.values()];
    for (const card of cards) {
      card.zone = "deck";
      card.ownerId = null;
      card.x = null;
      card.y = null;
      card.rotation = 0;
      card.faceUp = false;
      card.z = 0;
      card.handOrder = 0;
      delete card.bagId;
      card.locked = false;
    }
    rekeyCards(room, cards);
    for (const deck of room.decks.values()) {
      deck.order = shuffled(cards.filter((card) => card.deckId === deck.id).map((card) => card.id));
    }
    for (const [index, token] of [...room.tokens.values()].entries()) {
      delete token.bagId;
      token.x = token.homeX;
      token.y = token.homeY;
      token.z = index + 1;
    }
    room.die.value = null;
    room.die.rollId += 1;
    room.die.lastRolledBy = null;
    room.counter.value = room.counter.initial;
    room.turn.activePlayerId = null;
    room.nextHandOrder = 1;
    room.nextZ = Math.max(0, ...[...room.decks.values(), ...room.objects.values(), ...room.tokens.values()].map((item) => item.z || 0)) + 1;
    for (const object of room.objects.values()) {
      delete object.bagId;
      if (object.kind === "bag") object.contents = [];
    }
    addHistory(room, actor, "重置了桌面");
    touch(room);
    return;
  }

  throw new RoomError("UNKNOWN_COMMAND", "这个版本还不支持该操作。");
}

function exportRoomScene(room, playerId, name = room.title) {
  if (requirePlayer(room, playerId).role !== "host") throw new RoomError("HOST_ONLY", "只有房主可以保存整个桌面。", 403);
  const board = captureBoard(room);
  const decks = board.decks.map(([, deck]) => deck);
  const cards = board.cards.map(({ ownerId, handOrder, ...card }) => {
    if (card.zone === "hand") {
      Object.assign(card, { zone: "deck", x: null, y: null, rotation: 0, faceUp: false, locked: false, z: 0 });
      decks.find((deck) => deck.id === card.deckId).order.push(card.id);
    }
    return card;
  });
  for (const deck of decks) deck.order = shuffled(deck.order);
  return {
    format: "parlor.scene", version: 1, name: cleanName(name, room.title), savedAt: Date.now(),
    decks, cards, tokens: board.tokens.map(([, token]) => token), objects: board.objects.map(([, object]) => object),
    components: {
      die: { label: board.die.label, sides: board.die.sides, value: board.die.value },
      counter: { ...board.counter }
    }
  };
}

function validateRoomScene(scene) {
  const fail = (message) => { throw new RoomError("INVALID_SCENE", `存档无效：${message}`); };
  if (!scene || scene.format !== "parlor.scene" || scene.version !== 1) fail("需要 Parlor 的桌面存档文件。");
  for (const key of ["decks", "cards", "tokens", "objects"]) if (!Array.isArray(scene[key])) fail(`${key} 必须是数组。`);
  if (!scene.decks.length || scene.decks.length > 32 || scene.cards.length > 1500 || scene.tokens.length + scene.objects.length > 240) fail("物件数量超出桌面容量。");
  const ids = new Set();
  const readId = (value) => {
    if (typeof value !== "string" || !/^[a-zA-Z0-9_-]{1,80}$/.test(value) || ids.has(value)) fail("物件编号缺失或重复。");
    ids.add(value); return value;
  };
  const finite = (value, low, high) => {
    if (!Number.isFinite(value) || value < low || value > high) fail("位置或数值超出允许范围。");
    return value;
  };
  const position = (source) => ({
    x: finite(source.x, -4500, 6300), y: finite(source.y, -3000, 4100),
    z: finite(source.z || 0, 0, 1_000_000), rotation: finite(source.rotation || 0, -180, 180), locked: source.locked === true
  });
  const color = (value) => {
    if (typeof value !== "string" || !/^#[a-f0-9]{6}$/i.test(value)) fail("颜色需要使用 #RRGGBB 格式。");
    return value;
  };
  const image = (value) => { if (value) assertAssetPath(value, "图片"); return value || null; };
  const readSource = (source) => {
    if (!source?.back || typeof source.packId !== "string" || !/^[a-z0-9][a-z0-9-]{0,39}$/.test(source.packId)) fail("卡牌图片来源无效。");
    return { packId: source.packId, back: {
      label: cleanName(source.back.label, "PARLOR"), theme: cleanName(source.back.theme, "default"),
      color: color(source.back.color), image: image(source.back.image)
    } };
  };
  const decks = scene.decks.map((source) => {
    if (!source || !source.back || !Array.isArray(source.order)) fail("牌盒结构不完整。");
    if (typeof source.packId !== "string" || !/^[a-z0-9][a-z0-9-]{0,39}$/.test(source.packId)) fail("牌盒来源无效。");
    return {
      id: readId(source.id), label: cleanName(source.label, "牌盒"), packId: source.packId, ...position(source), order: [...source.order], hidden: source.hidden === true,
      back: { label: cleanName(source.back.label, "PARLOR"), theme: cleanName(source.back.theme, "default"), color: color(source.back.color), image: image(source.back.image) }
    };
  });
  if (!decks.some((deck) => deck.id === "main")) fail("缺少起始牌盒。");
  if (decks.some((deck) => deck.hidden && deck.order.length)) fail("收起的牌堆不能仍装着牌。");
  const deckIds = new Set(decks.map((deck) => deck.id));
  const cards = scene.cards.map((source, index) => {
    if (!source?.face || !deckIds.has(source.deckId) || !["deck", "public", "bag"].includes(source.zone)) fail("卡牌区域或来源无效。");
    const face = {};
    for (const key of ["label", "rank", "suit", "symbol", "tone", "color", "textColor", "image"]) {
      if (source.face[key] !== null && source.face[key] !== undefined) face[key] = source.face[key];
    }
    validateGamePack({
      id: "scene-validation", name: "存档", version: 1,
      cardBack: { label: "存档", color: "#234434" }, die: { label: "D6", sides: 6 }, cards: [{ key: `card-${index}`, ...face }]
    });
    for (const key of ["color", "textColor", "image"]) if (face[key] === undefined) face[key] = null;
    return {
      id: readId(source.id), deckId: source.deckId, source: readSource(source.source || decks.find((deck) => deck.id === source.deckId)), face, zone: source.zone,
      ...(source.zone === "public" ? position(source) : { x: null, y: null, z: 0, rotation: finite(source.rotation || 0, -180, 180), locked: false }),
      ownerId: null, handOrder: 0, faceUp: source.zone !== "bag" && source.faceUp === true,
      ...(source.zone === "bag" ? { bagId: String(source.bagId || "") } : {})
    };
  });
  const tokens = scene.tokens.map((source) => {
    if (!source) fail("标记无效。");
    return {
      id: readId(source.id), key: cleanName(source.key, "token"), label: cleanName(source.label, "标记"),
      symbol: Array.from(String(source.symbol ?? "")).slice(0, 8).join(""), color: color(source.color),
      ...position(source), homeX: finite(source.homeX ?? source.x, -4500, 6300), homeY: finite(source.homeY ?? source.y, -3000, 4100),
      image: image(source.image), packId: typeof source.packId === "string" ? source.packId.slice(0, 40) : undefined,
      ...(source.bagId ? { bagId: String(source.bagId) } : {})
    };
  });
  const objects = scene.objects.map((source) => {
    const preset = RESOURCE_CATALOG.find((entry) => entry.id === source?.resourceId && entry.kind === source.kind);
    if (!preset || preset.kind === "token") fail("未知物件类型。");
    const object = {
      ...preset, id: readId(source.id), resourceId: preset.id, ...position(source), label: cleanName(source.label, preset.label),
      color: color(source.color), ...(source.bagId ? { bagId: String(source.bagId) } : {})
    };
    delete object.description;
    if (object.kind === "note") {
      if (typeof source.text !== "string" || source.text.length > 600) fail("便签超过 600 字。");
      object.text = source.text;
    }
    if (["die", "counter"].includes(object.kind)) {
      if (source.value !== null && !Number.isInteger(source.value)) fail("计数必须是整数。");
      object.value = object.kind === "die" && source.value === null ? null : finite(source.value, object.kind === "die" ? 1 : -9999, object.kind === "die" ? preset.sides : 9999);
      object.rollId = 0;
    }
    if (object.kind === "bag") {
      if (!Array.isArray(source.contents) || source.contents.length > 1740 || source.bagId) fail("袋子结构无效。");
      object.contents = source.contents.map((entry) => {
        if (!entry || !["card", "token", "object"].includes(entry.type) || typeof entry.id !== "string") fail("袋中物件无效。");
        return { type: entry.type, id: entry.id };
      });
    }
    return object;
  });
  const resources = { card: new Map(cards.map((card) => [card.id, card])), token: new Map(tokens.map((token) => [token.id, token])), object: new Map(objects.map((object) => [object.id, object])) };
  const assigned = new Set();
  for (const deck of decks) {
    for (const id of deck.order) {
      const card = resources.card.get(id);
      if (!card || card.zone !== "deck" || card.deckId !== deck.id || assigned.has(id)) fail("牌堆中有重复或不存在的牌。");
      assigned.add(id);
    }
  }
  for (const bag of objects.filter((object) => object.kind === "bag")) {
    for (const entry of bag.contents) {
      const resource = resources[entry.type].get(entry.id);
      if (!resource || resource.bagId !== bag.id || ["bag", "mat"].includes(resource.kind) || assigned.has(resource.id)) fail("袋子内容不一致。");
      assigned.add(resource.id);
    }
  }
  for (const resource of [...cards, ...tokens, ...objects]) {
    if ((resource.bagId || resource.zone === "deck" || resource.zone === "bag") && !assigned.has(resource.id)) fail("有物件缺少所属容器。");
  }
  let components = null;
  if (scene.components) {
    const { die, counter } = scene.components;
    if (!die || !counter) fail("游戏组件不完整。");
    const integer = (value, low, high) => { if (!Number.isInteger(value)) fail("组件数值必须是整数。"); return finite(value, low, high); };
    const sides = integer(die.sides, 2, 20);
    const min = integer(counter.min, -9999, 9999), max = integer(counter.max, min, 9999);
    components = {
      die: { label: cleanName(die.label, "公共骰子"), sides, value: die.value === null ? null : integer(die.value, 1, sides), rollId: 0, lastRolledBy: null },
      counter: { label: cleanName(counter.label, "计数"), initial: integer(counter.initial, min, max), min, max, value: integer(counter.value, min, max) }
    };
  }
  return { name: cleanName(scene.name, "朋友的桌面"), decks, cards, tokens, objects, components };
}

function restoreRoomScene(room, playerId, scene) {
  const actor = requirePlayer(room, playerId);
  if (actor.role !== "host") throw new RoomError("HOST_ONLY", "只有房主可以恢复桌面存档。", 403);
  const loaded = validateRoomScene(scene);
  const newCardIds = new Map(loaded.cards.map((card) => [card.id, `card_${randomUUID().replaceAll("-", "")}`]));
  for (const deck of loaded.decks) deck.order = shuffled(deck.order.map((id) => newCardIds.get(id)));
  for (const bag of loaded.objects.filter((object) => object.kind === "bag")) {
    bag.contents = bag.contents.map((entry) => entry.type === "card" ? { ...entry, id: newCardIds.get(entry.id) } : entry);
  }
  for (const card of loaded.cards) card.id = newCardIds.get(card.id);
  saveUndoPoint(room);
  room.epoch = randomUUID();
  room.cards = new Map(loaded.cards.map((card) => [card.id, card]));
  room.decks = new Map(loaded.decks.map((deck) => [deck.id, deck]));
  room.tokens = new Map(loaded.tokens.map((token) => [token.id, token]));
  room.objects = new Map(loaded.objects.map((object) => [object.id, object]));
  if (loaded.components) {
    room.die = loaded.components.die;
    room.counter = loaded.components.counter;
  }
  room.title = loaded.name;
  const main = room.decks.get("main");
  room.pack = { id: main.packId, name: main.label, version: 1, cardBack: main.back };
  room.nextZ = Math.max(1, ...loaded.decks.map((deck) => deck.z), ...loaded.cards.map((card) => card.z), ...loaded.tokens.map((token) => token.z), ...loaded.objects.map((object) => object.z)) + 1;
  room.nextHandOrder = 1;
  room.turn.activePlayerId = null;
  addHistory(room, actor, `恢复了桌面「${loaded.name}」`, { action: "restore-scene" });
  touch(room);
}

function snapshotRoomGame(room, name = room.title) {
  const board = captureBoard(room);
  const hands = [];
  const cards = board.cards.map((card) => {
    const copy = structuredClone(card);
    if (copy.zone === "hand") {
      hands.push({ cardId: copy.id, ownerId: copy.ownerId, handOrder: copy.handOrder, faceUp: copy.faceUp === true });
      Object.assign(copy, privateCardPosition(room, card), { zone: "public", faceUp: false });
    }
    delete copy.ownerId; delete copy.handOrder;
    return copy;
  });
  return {
    format: "parlor.game", version: 1, gameId: room.gameId,
    name: cleanName(name, room.title), savedAt: Date.now(), maxPlayers: room.maxPlayers,
    players: [...room.players.values()].map((player) => ({
      id: player.id, name: player.name, color: player.color, role: player.role,
      seatIndex: player.seatIndex, recoveryKey: player.recoveryKey,
      privateZone: { ...privateZoneForPlayer(room, player.id) }
    })),
    hands, turnPlayerId: room.turn.activePlayerId,
    table: {
      format: "parlor.scene", version: 1, name: cleanName(name, room.title),
      decks: board.decks.map(([, deck]) => deck), cards,
      tokens: board.tokens.map(([, token]) => token), objects: board.objects.map(([, object]) => object),
      components: { die: { ...board.die }, counter: { ...board.counter } }
    },
    templates: board.templates.map(([, template]) => template),
    history: structuredClone(room.history), messages: structuredClone(room.messages)
  };
}

function exportRoomGame(room, playerId, name = room.title) {
  if (requirePlayer(room, playerId).role !== "host") throw new RoomError("HOST_ONLY", "只有房主可以保存完整对局。", 403);
  return snapshotRoomGame(room, name);
}

function validateRoomGame(game, { allowEmpty = false } = {}) {
  const fail = (message) => { throw new RoomError("INVALID_GAME", `对局存档无效：${message}`); };
  if (!game || game.format !== "parlor.game" || game.version !== 1) fail("需要 Parlor 的完整对局文件。");
  const validId = (id) => typeof id === "string" && /^[\w-]{1,80}$/.test(id);
  if (!validId(game.gameId)) fail("缺少对局编号。");
  if (!Number.isInteger(game.maxPlayers) || game.maxPlayers < 2 || game.maxPlayers > 8) fail("席位数量需要 2–8 个。");
  if (!Array.isArray(game.players) || game.players.length > game.maxPlayers || (!allowEmpty && !game.players.length)) fail("玩家列表无效。");
  const playerIds = new Set(), keys = new Set(), seats = new Set(), names = new Set();
  const players = game.players.map((source) => {
    if (!source || !validId(source.id) || playerIds.has(source.id) || !["host", "guest"].includes(source.role)) fail("玩家编号缺失或重复。");
    if (!Number.isInteger(source.seatIndex) || source.seatIndex < 0 || source.seatIndex >= game.maxPlayers || seats.has(source.seatIndex)) fail("席位重复或越界。");
    if (typeof source.recoveryKey !== "string" || !/^[a-f0-9]{64}$/.test(source.recoveryKey) || keys.has(source.recoveryKey)) fail("个人续局口令缺失或重复。");
    if (!/^#[a-f0-9]{6}$/i.test(source.color || "")) fail("玩家颜色无效。");
    const name = cleanName(source.name, "玩家");
    if (names.has(name)) fail("玩家昵称重复。");
    const zone = source.privateZone || privateZoneForSeat(source.seatIndex);
    if (![zone.x, zone.y, zone.width, zone.height].every(Number.isFinite) || zone.width < 360 || zone.width > 1600 || zone.height < 250 || zone.height > 1200
      || zone.x < -4500 || zone.y < -3000 || zone.x + zone.width > 6300 || zone.y + zone.height > 4100) fail("私人区范围无效。");
    playerIds.add(source.id); keys.add(source.recoveryKey); seats.add(source.seatIndex); names.add(name);
    return { id: source.id, name, color: source.color, role: source.role, seatIndex: source.seatIndex, recoveryKey: source.recoveryKey, privateZone: { x: zone.x, y: zone.y, width: zone.width, height: zone.height } };
  });
  const hosts = players.filter((player) => player.role === "host");
  if (hosts.length > 1 || (!allowEmpty && hosts.length !== 1) || hosts.some((player) => player.seatIndex !== 0)
    || players.some((player) => player.role !== "host" && player.seatIndex === 0)) fail("房主席位无效。");
  let table;
  try { table = validateRoomScene(game.table); } catch (error) { fail(error.message); }
  if (!table.components) fail("缺少游戏组件。");
  if (!Array.isArray(game.hands) || game.hands.length > table.cards.length) fail("私人牌列表无效。");
  const cardMap = new Map(table.cards.map((card) => [card.id, card])), assigned = new Set();
  for (const hand of game.hands) {
    const card = cardMap.get(hand?.cardId);
    if (!card || card.zone !== "public" || card.faceUp || assigned.has(card.id) || !playerIds.has(hand.ownerId)) fail("私人牌的归属或区域不一致。");
    if (!Number.isSafeInteger(hand.handOrder) || hand.handOrder < 1 || hand.handOrder > 1000000) fail("私人牌顺序无效。");
    if (hand.faceUp !== undefined && typeof hand.faceUp !== "boolean") fail("手牌展示状态无效。");
    assigned.add(card.id);
    Object.assign(card, { zone: "hand", ownerId: hand.ownerId, handOrder: hand.handOrder, faceUp: hand.faceUp === true });
  }
  if (game.turnPlayerId !== null && game.turnPlayerId !== undefined && !playerIds.has(game.turnPlayerId)) fail("行动玩家不在席位中。");
  if (!Array.isArray(game.templates) || game.templates.length > 40) fail("本桌资源库无效。");
  const templateIds = new Set();
  const templates = game.templates.map((source) => {
    if (!source || !validId(source.id) || templateIds.has(source.id) || !["deck", "object", "token"].includes(source.type) || !source.resource || !Array.isArray(source.cards)) fail("收藏资源结构无效。");
    templateIds.add(source.id);
    const originalId = source.resource.id;
    if (!validId(originalId)) fail("收藏物件编号无效。");
    const sample = { format: "parlor.scene", version: 1, decks: [{ ...table.decks.find((deck) => deck.id === "main"), order: [] }], cards: [], tokens: [], objects: [] };
    if (source.type === "deck") {
      sample.decks = [{ ...source.resource, id: "main" }];
      sample.cards = source.cards.map((card) => ({ ...card, deckId: "main", zone: "deck" }));
    } else {
      if (source.cards.length || source.resource.bagId || source.resource.contents?.length) fail("收藏不能携带容器中的物件。");
      sample[source.type === "token" ? "tokens" : "objects"] = [source.resource];
    }
    let validated;
    try { validated = validateRoomScene(sample); } catch (error) { fail(error.message); }
    const resource = source.type === "deck" ? validated.decks[0] : source.type === "token" ? validated.tokens[0] : validated.objects[0];
    resource.id = originalId;
    const cards = validated.cards.map((card) => ({ ...card, deckId: originalId }));
    return { id: source.id, label: cleanName(source.label, resource.label), type: source.type, kind: source.type === "deck" ? "deck" : resource.kind || "token", resource, cards,
      creatorId: validId(source.creatorId) ? source.creatorId : "", count: source.type === "deck" ? cards.length : 1 };
  });
  if (!Array.isArray(game.history) || game.history.length > 500) fail("操作历史无效。");
  const history = game.history.map((entry) => {
    if (!entry || !validId(entry.id) || !validId(entry.actorId) || !Number.isFinite(entry.at) || entry.at < 0 || typeof entry.label !== "string" || entry.label.length > 600) fail("操作记录不完整。");
    return { id: entry.id, at: entry.at, actorId: entry.actorId, actorName: cleanName(entry.actorName, "玩家"),
      actorColor: /^#[a-f0-9]{6}$/i.test(entry.actorColor || "") ? entry.actorColor : "#7b946d", label: entry.label,
      action: typeof entry.action === "string" ? entry.action.slice(0, 60) : "table",
      ...(validId(entry.undoOf) ? { undoOf: entry.undoOf } : {}) };
  });
  if (!Array.isArray(game.messages || []) || (game.messages || []).length > 60) fail("聊天记录无效。");
  const messages = (game.messages || []).map((message) => {
    if (!message || !validId(message.id) || !validId(message.playerId) || !Number.isFinite(message.at)
      || typeof message.text !== "string" || Array.from(message.text).length > 280) fail("聊天记录不完整。");
    return { id: message.id, playerId: message.playerId, at: message.at, text: message.text,
      name: cleanName(message.name, "玩家"), color: safeTokenColor(message.color) };
  });
  if (game.holdem) migrateLegacyHoldem(game.holdem, { players, table, history, fail });
  return { gameId: game.gameId, name: cleanName(game.name, table.name), maxPlayers: game.maxPlayers, players, table, templates, history, messages,
    turnPlayerId: game.holdem ? null : game.turnPlayerId || null };
}

// Read old saves without retaining an executable betting/rules system.
function migrateLegacyHoldem(legacy, { players, table, history, fail }) {
  const deck = table.decks.find((entry) => entry.id === legacy.deckId);
  const mat = table.objects.find((entry) => entry.id === legacy.matId);
  if (!deck || !mat || !Array.isArray(legacy.players) || legacy.players.length > 8) fail("旧德州资源记录不完整。");
  const seen = new Set();
  const balances = legacy.players.map((entry) => {
    const player = players.find((candidate) => candidate.id === entry.playerId);
    if (!player || seen.has(player.id) || ![entry.stack, entry.committed].every((n) => Number.isSafeInteger(n) && n >= 0 && n <= 8_000_000)) fail("旧德州筹码记录无效。");
    seen.add(player.id);
    return { player, stack: entry.stack, committed: entry.committed };
  });
  if (balances.reduce((sum, entry) => sum + entry.stack + entry.committed, 0) !== legacy.totalChips) fail("旧德州筹码总数不一致。");
  deck.locked = false; mat.locked = false;
  for (const card of table.cards) if (card.deckId === deck.id) card.locked = false;
  let z = Math.max(0, ...[...table.cards, ...table.decks, ...table.objects, ...table.tokens].map((item) => item.z)) + 1;
  for (const { player, stack, committed } of balances) {
    for (const [index, amount] of [stack, committed].entries()) {
      if (!amount || table.tokens.length + table.objects.length >= 240) continue;
      const point = publicTokenDropPoint({ x: player.privateZone.x + 100 + index * 90, y: player.privateZone.y + player.privateZone.height - 90 });
      table.tokens.push({ id: `token_${randomUUID().replaceAll("-", "")}`, key: "legacy-chips",
        label: cleanName(`${player.name} · ${index ? "已下注" : "余筹"}`, "筹码"), symbol: String(amount), color: player.color,
        ...point, homeX: point.x, homeY: point.y, z: z++, rotation: 0, locked: false, image: null });
    }
  }
  // The audit retains every balance even if an old table is at object capacity.
  const host = players.find((player) => player.role === "host");
  history.push({ id: randomUUID(), at: Date.now(), actorId: host?.id || players[0].id, actorName: host?.name || "房主", actorColor: host?.color || "#568775",
    action: "legacy-resources", label: `旧德州已改为自由桌面，筹码（余筹 / 已下注）：${balances.map(({ player, stack, committed }) => `${player.name} ${stack} / ${committed}`).join("；")}。` });
  if (history.length > 500) history.splice(0, history.length - 500);
}

function installGameBoard(room, loaded, playerMap = new Map(), { rekey = false } = {}) {
  const { table } = loaded;
  const cardMap = new Map(table.cards.map((card) => [card.id, rekey ? `card_${randomUUID().replaceAll("-", "")}` : card.id]));
  for (const card of table.cards) {
    card.id = cardMap.get(card.id);
    if (card.ownerId) card.ownerId = playerMap.get(card.ownerId) || card.ownerId;
  }
  for (const deck of table.decks) deck.order = deck.order.map((id) => cardMap.get(id));
  for (const bag of table.objects.filter((object) => object.kind === "bag")) for (const entry of bag.contents) if (entry.type === "card") entry.id = cardMap.get(entry.id);
  room.cards = new Map(table.cards.map((card) => [card.id, card]));
  room.decks = new Map(table.decks.map((deck) => [deck.id, deck]));
  room.tokens = new Map(table.tokens.map((token) => [token.id, token]));
  room.objects = new Map(table.objects.map((object) => [object.id, object]));
  room.templates = new Map(loaded.templates.map((template) => [template.id, { ...template, creatorId: playerMap.get(template.creatorId) || template.creatorId }]));
  room.die = table.components.die; room.counter = table.components.counter;
  room.turn = { activePlayerId: playerMap.get(loaded.turnPlayerId) || loaded.turnPlayerId };
  room.title = loaded.name; room.gameId = loaded.gameId; room.maxPlayers = loaded.maxPlayers;
  const main = room.decks.get("main");
  room.pack = { id: main.packId, name: main.label, version: 1, cardBack: main.back };
  room.nextZ = Math.max(0, ...[...room.cards.values(), ...room.decks.values(), ...room.tokens.values(), ...room.objects.values()].map((item) => item.z || 0)) + 1;
  room.nextHandOrder = Math.max(0, ...table.cards.map((card) => card.handOrder || 0)) + 1;
  room.cardRequests.clear();
}

function restoreRoomGame(room, playerId, game) {
  const actor = requirePlayer(room, playerId);
  if (actor.role !== "host") throw new RoomError("HOST_ONLY", "只有房主可以恢复完整对局。", 403);
  const loaded = validateRoomGame(game);
  if (loaded.players.some((saved) => saved.role !== "host" && saved.recoveryKey === actor.recoveryKey)) throw new RoomError("INVALID_GAME", "续局口令与当前房主席位冲突。");
  const playerMap = new Map(), players = new Map(), kept = new Set([actor.id]);
  for (const saved of [...loaded.players].sort((a, b) => a.seatIndex - b.seatIndex)) {
    const id = saved.role === "host" ? actor.id : saved.id === actor.id ? `player_${randomUUID().replaceAll("-", "")}` : saved.id;
    playerMap.set(saved.id, id);
    const current = room.players.get(id);
    const matched = current && (saved.role === "host" || current.recoveryKey === saved.recoveryKey);
    if (matched) kept.add(id);
    players.set(id, { ...saved, id, name: uniqueName({ players }, saved.role === "host" ? actor.name : saved.name, "玩家"),
      recoveryKey: saved.role === "host" ? actor.recoveryKey : saved.recoveryKey,
      connections: matched ? current.connections : 0, joinedAt: matched ? current.joinedAt : Date.now(), lastSeenAt: Date.now() });
  }
  const audit = new Map(room.history.map((entry) => [entry.id, entry]));
  for (const entry of loaded.history) if (!audit.has(entry.id)) audit.set(entry.id, { ...entry, actorId: playerMap.get(entry.actorId) || entry.actorId });
  installGameBoard(room, loaded, playerMap, { rekey: true });
  room.epoch = randomUUID();
  room.players = players;
  room.sessions = new Map([...room.sessions].filter(([, id]) => kept.has(id)));
  room.history = [...audit.values()].sort((a, b) => a.at - b.at).slice(-499);
  room.messages = loaded.messages.map((message) => ({ ...message, playerId: playerMap.get(message.playerId) || message.playerId }));
  room.undoStack = [];
  room.nextGuestNumber = players.size + 1; room.nextSeatIndex = Math.max(...[...players.values()].map((player) => player.seatIndex)) + 1;
  addHistory(room, players.get(actor.id), `恢复了对局「${loaded.name}」`, { action: "restore-game" });
  touch(room);
}

function exportRoomCheckpoint(room) {
  return {
    format: "parlor.room", version: 1, code: room.code, hostSecret: room.hostSecret, hostName: room.hostName,
    revision: room.revision, epoch: room.epoch, receiptFloorRevision: room.receiptFloorRevision, savedAt: Date.now(), game: snapshotRoomGame(room),
    sessions: [...room.sessions], commandReceipts: [...room.commandReceipts], messages: structuredClone(room.messages)
  };
}

function roomFromCheckpoint(checkpoint) {
  if (!checkpoint || checkpoint.format !== "parlor.room" || checkpoint.version !== 1 || typeof checkpoint.code !== "string" || !/^[A-Z0-9-]{3,24}$/.test(checkpoint.code)
    || typeof checkpoint.hostSecret !== "string" || checkpoint.hostSecret.length < 8 || checkpoint.hostSecret.length > 256
    || !Number.isSafeInteger(checkpoint.revision) || checkpoint.revision < 0) throw new RoomError("INVALID_CHECKPOINT", "房间续局文件不完整或版本不支持。");
  const loaded = validateRoomGame(checkpoint.game, { allowEmpty: true });
  const main = loaded.table.decks.find((deck) => deck.id === "main");
  const room = createRoom({ code: checkpoint.code, hostSecret: checkpoint.hostSecret, hostName: checkpoint.hostName,
    pack: { id: main.packId, name: main.label, version: 1, die: { label: "D6", sides: 6 }, cardBack: { label: main.back.label, theme: main.back.theme, color: main.back.color, ...(main.back.image ? { image: main.back.image } : {}) }, cards: [{ key: "bootstrap", label: "占位", rank: "1", suit: "none", symbol: "●" }] } });
  installGameBoard(room, loaded);
  room.players = new Map(loaded.players.map((player) => [player.id, { ...player, connections: 0, joinedAt: checkpoint.savedAt || Date.now(), lastSeenAt: Date.now() }]));
  if (!Array.isArray(checkpoint.sessions) || checkpoint.sessions.length > 1024) throw new RoomError("INVALID_CHECKPOINT", "房间连接记录无效。");
  for (const entry of checkpoint.sessions) {
    if (!Array.isArray(entry) || entry.length !== 2 || typeof entry[0] !== "string" || !/^[a-f0-9]{64}$/.test(entry[0]) || !room.players.has(entry[1])) throw new RoomError("INVALID_CHECKPOINT", "房间连接凭据无效。");
  }
  room.sessions = new Map(checkpoint.sessions);
  if (!Array.isArray(checkpoint.commandReceipts || []) || (checkpoint.commandReceipts || []).length > 1024) throw new RoomError("INVALID_CHECKPOINT", "操作回执记录无效。");
  for (const entry of checkpoint.commandReceipts || []) {
    if (!Array.isArray(entry) || entry.length !== 2) throw new RoomError("INVALID_CHECKPOINT", "操作回执格式无效。");
    const [key, receipt] = entry;
    if (typeof key !== "string" || key.length > 200 || !receipt || !/^[a-f0-9]{64}$/.test(receipt.fingerprint || "") || !Number.isSafeInteger(receipt.revision)) throw new RoomError("INVALID_CHECKPOINT", "操作回执格式无效。");
    const created = receipt.createdResource;
    if (created && (!["card", "deck", "token", "object"].includes(created.type) || typeof created.id !== "string" || !/^[\w-]{1,80}$/.test(created.id))) throw new RoomError("INVALID_CHECKPOINT", "物件回执格式无效。");
    room.commandReceipts.set(key, { fingerprint: receipt.fingerprint, revision: receipt.revision, ...(created ? { createdResource: { type: created.type, id: created.id } } : {}) });
  }
  room.history = loaded.history;
  room.messages = loaded.messages;
  if (typeof checkpoint.epoch === "string" && /^[\w-]{1,80}$/.test(checkpoint.epoch)) room.epoch = checkpoint.epoch;
  if (Number.isSafeInteger(checkpoint.receiptFloorRevision) && checkpoint.receiptFloorRevision >= -1) room.receiptFloorRevision = checkpoint.receiptFloorRevision;
  room.revision = checkpoint.revision + 1;
  room.nextGuestNumber = room.players.size + 1; room.nextSeatIndex = Math.max(0, ...loaded.players.map((player) => player.seatIndex)) + 1;
  return room;
}

function projectRoom(room, viewerId) {
  const viewer = requirePlayer(room, viewerId);
  const players = [...room.players.values()]
    .sort((left, right) => left.seatIndex - right.seatIndex)
    .map((player) => ({
      id: player.id,
      name: player.name,
      color: player.color,
      role: player.role,
      privateZone: { ...privateZoneForPlayer(room, player.id) },
      seatIndex: player.seatIndex,
      online: player.connections > 0
    }));

  const cards = [...room.cards.values()]
    .filter((card) => !["deck", "bag"].includes(card.zone))
    .sort((left, right) => {
      if (left.zone === "hand" && right.zone === "hand") return left.handOrder - right.handOrder;
      return left.z - right.z;
    })
    .map((card) => {
      const canSeeFace = (card.zone === "public" && card.faceUp) || (card.zone === "hand" && (card.ownerId === viewer.id || card.faceUp));
      const position = card.zone === "hand" ? privateCardPosition(room, card) : card;
      return {
        id: card.id,
        deckId: card.deckId,
        back: projectBack(cardSource(room, card).back),
        locked: Boolean(card.locked),
        zone: card.zone,
        ownerId: card.ownerId,
        x: position.x,
        y: position.y,
        rotation: card.rotation,
        faceUp: card.faceUp,
        z: position.z,
        handOrder: card.handOrder,
        face: canSeeFace
          ? {
              label: card.face.label,
              rank: card.face.rank,
              suit: card.face.suit,
              symbol: card.face.symbol,
              tone: card.face.tone,
              color: card.face.color,
              textColor: card.face.textColor,
              hasImage: Boolean(card.face.image)
            }
          : null,
        canControl: canControlCard(viewer, card),
        canFlip: card.zone === "public" || card.ownerId === viewer.id
      };
    });

  const tokens = [...room.tokens.values()]
    .filter((token) => !token.bagId)
    .sort((left, right) => left.z - right.z)
    .map((token) => ({
      id: token.id,
      locked: Boolean(token.locked),
      key: token.key,
      label: token.label,
      symbol: token.symbol,
      color: token.color,
      hasImage: Boolean(token.image),
      x: token.x,
      y: token.y,
      z: token.z,
      canControl: true
    }));

  return {
    type: "room-state",
    revision: room.revision,
    serverTime: Date.now(),
    room: {
      code: room.code,
      gameId: room.gameId,
      epoch: room.epoch,
      title: room.title,
      shareUrl: room.shareUrl,
      maxPlayers: room.maxPlayers,
      pack: {
        id: room.pack.id,
        name: room.pack.name,
        version: room.pack.version,
        cardBack: {
          label: room.pack.cardBack.label,
          theme: room.pack.cardBack.theme,
          color: room.pack.cardBack.color,
          hasImage: Boolean(room.pack.cardBack.image)
        }
      },
      packOptions: (Array.isArray(room.packOptions) && room.packOptions.length > 0
        ? room.packOptions
        : [{ id: room.pack.id, name: room.pack.name, cardCount: room.cards.size }]
      ).map((pack) => ({
        id: String(pack.id ?? "").slice(0, 40),
        name: cleanName(pack.name, "未命名牌盒"),
        cardCount: Math.max(0, Number(pack.cardCount) || 0)
      })),
      geometry: TABLE_GEOMETRY
    },
    you: {
      id: viewer.id,
      name: viewer.name,
      color: viewer.color,
      role: viewer.role,
      recoveryKey: viewer.recoveryKey
    },
    players,
    deck: {
      count: room.deckOrder.length,
      canDraw: room.deckOrder.length > 0
    },
    cards,
    tokens,
    decks: [...room.decks.values()].filter((deck) => !deck.hidden).map((deck) => ({
      id: deck.id, label: deck.label, packId: deck.packId, back: projectBack(deck.back),
      x: deck.x, y: deck.y, z: deck.z, locked: Boolean(deck.locked),
      count: deck.order.length, canDraw: deck.order.length > 0,
      top: deck.order.length ? (() => {
        const card = room.cards.get(deck.order.at(-1));
        return { id: card.id, faceUp: card.faceUp, rotation: card.rotation, back: projectBack(cardSource(room, card).back), face: card.faceUp ? projectFace(card.face) : null };
      })() : null,
      publicCount: [...room.cards.values()].filter((card) => card.deckId === deck.id && card.zone === "public").length
    })),
    objects: [...room.objects.values()].filter((object) => !object.bagId).map(({ contents, ...object }) => ({
      ...structuredClone(object), ...(contents ? { count: contents.length } : {})
    })),
    templates: [...room.templates.values()].map((template) => ({ id: template.id, label: template.label, kind: template.kind, count: template.count, canDelete: viewer.role === "host" || template.creatorId === viewer.id })),
    messages: room.messages.slice(-60),
    die: { ...room.die },
    counter: { ...room.counter },
    turn: { ...room.turn },
    canUndo: viewer.role === "host" && room.undoStack.length > 0,
    persistence: { ...room.persistence },
    history: room.history.slice(-500)
  };
}

function roomSummary(room) {
  return {
    roomAvailable: true,
    roomCode: room.code,
    gameId: room.gameId,
    roomTitle: room.title,
    packName: room.pack.name,
    playerCount: room.players.size,
    maxPlayers: room.maxPlayers,
    defaultGuestName: uniqueName(room, "", `玩家${room.nextGuestNumber}`),
    shareUrl: room.shareUrl
  };
}

